--
-- Table structure for table `banners`
--

DROP TABLE IF EXISTS `banners`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `banners` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `title` varchar(160) NOT NULL,
  `subtitle` varchar(240) DEFAULT NULL,
  `image_path` varchar(255) NOT NULL COMMENT 'Desktop / wide artwork',
  `mobile_image_path` varchar(255) DEFAULT NULL COMMENT 'Portrait artwork for the apps',
  `alt_text` varchar(180) DEFAULT NULL,
  `placement` enum('home_hero','home_strip','category_top','app_home','checkout') NOT NULL DEFAULT 'home_hero',
  `link_type` enum('none','category','product','url','offer','collection') NOT NULL DEFAULT 'none',
  `link_value` varchar(255) DEFAULT NULL COMMENT 'Category/product slug, URL, or offer code',
  `cta_label` varchar(60) DEFAULT NULL,
  `display_order` smallint(5) unsigned NOT NULL DEFAULT 100,
  `start_date` datetime DEFAULT NULL,
  `end_date` datetime DEFAULT NULL,
  `impression_count` int(10) unsigned NOT NULL DEFAULT 0,
  `click_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_banners_uuid` (`uuid`),
  KEY `idx_banners_placement` (`placement`,`is_active`,`is_deleted`,`display_order`),
  KEY `idx_banners_window` (`start_date`,`end_date`),
  CONSTRAINT `chk_banners_window` CHECK (`start_date` is null or `end_date` is null or `end_date` > `start_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
