CREATE TABLE `courier_selections` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `order_id` bigint(20) unsigned NOT NULL,
  `shipment_id` bigint(20) unsigned DEFAULT NULL,
  `selected_courier_id` bigint(20) unsigned DEFAULT NULL,
  `strategy` varchar(40) NOT NULL DEFAULT 'balanced',
  `destination_pincode` varchar(10) NOT NULL,
  `chargeable_weight_grams` int(10) unsigned NOT NULL,
  `order_value` decimal(12,2) NOT NULL,
  `candidates_considered` smallint(5) unsigned NOT NULL DEFAULT 0,
  `candidates_eligible` smallint(5) unsigned NOT NULL DEFAULT 0,
  `winning_score` decimal(6,3) DEFAULT NULL,
  `reason` varchar(500) NOT NULL,
  `candidates` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Every courier considered, its score and why it won or lost' CHECK (json_valid(`candidates`)),
  `was_manual_override` tinyint(1) NOT NULL DEFAULT 0,
  `overridden_by` bigint(20) unsigned DEFAULT NULL,
  `override_reason` varchar(255) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_courier_selections_uuid` (`uuid`),
  KEY `idx_courier_selections_order` (`order_id`),
  KEY `idx_courier_selections_courier` (`selected_courier_id`),
  KEY `fk_courier_selections_shipment` (`shipment_id`),
  CONSTRAINT `fk_courier_selections_courier` FOREIGN KEY (`selected_courier_id`) REFERENCES `couriers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_courier_selections_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_courier_selections_shipment` FOREIGN KEY (`shipment_id`) REFERENCES `shipments` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
