INSERT INTO `courier_selections` VALUES (1,'e6916e92-b6cd-461c-8413-f360d5932165',1,1,4,'manual','587313',9600,3132.10,0,0,NULL,'Courier chosen manually by staff, bypassing automatic selection.','[]',1,2,NULL,2,'2026-09-15 20:37:36',NULL,NULL,NULL,NULL,1,0,1),(2,'34dd585b-7d6f-4596-b905-35fe6f7bd9c7',2,2,1,'balanced','587313',7200,2019.10,6,5,0.897,'Delhivery chosen on best balance of cost, speed and reliability: ₹234.60, 1-3 days, 88% reliability. Scored 0.897 against 5 eligible couriers. Next best was XpressBees at ₹217.40 (0.848).','[{\"courier_id\":1,\"courier_code\":\"DELHIVERY\",\"courier_name\":\"Delhivery\",\"cost\":234.6,\"sla_min_days\":1,\"sla_max_days\":3,\"reliability_score\":88,\"is_express\":false,\"is_eligible\":true,\"ineligibility_reasons\":[],\"cost_source\":\"rate_card\",\"score\":0.8966,\"cost_score\":0.9611,\"speed_score\":0.8,\"reliability_component\":0.88},{\"courier_id\":3,\"courier_code\":\"XPRESSBEES\",\"courier_name\":\"XpressBees\",\"cost\":217.4,\"sla_min_days\":2,\"sla_max_days\":4,\"reliability_score\":84,\"is_express\":false,\"is_eligible\":true,\"ineligibility_reasons\":[],\"cost_source\":\"rate_card\",\"score\":0.848,\"cost_score\":1,\"speed_score\":0.6,\"reliability_component\":0.84},{\"courier_id\":2,\"courier_code\":\"BLUEDART\",\"courier_name\":\"Blue Dart\",\"cost\":380.6,\"sla_min_days\":1,\"sla_max_days\":2,\"reliability_score\":92,\"is_express\":true,\"is_eligible\":true,\"ineligibility_reasons\":[],\"cost_source\":\"rate_card\",\"score\":0.7996,\"cost_score\":0.6313,\"speed_score\":1,\"reliability_component\":0.92},{\"courier_id\":4,\"courier_code\":\"DTDC\",\"courier_name\":\"DTDC\",\"cost\":274.08,\"sla_min_days\":2,\"sla_max_days\":5,\"reliability_score\":79,\"is_express\":false,\"is_eligible\":true,\"ineligibility_reasons\":[],\"cost_source\":\"rate_card\",\"score\":0.714,\"cost_score\":0.8719,\"speed_score\":0.4,\"reliability_component\":0.79},{\"courier_id\":6,\"courier_code\":\"SANDBOX\",\"courier_name\":\"Sandbox Courier\",\"cost\":660,\"sla_min_days\":3,\"sla_max_days\":7,\"reliability_score\":75,\"is_express\":false,\"is_eligible\":true,\"ineligibility_reasons\":[],\"cost_source\":\"rate_card\",\"score\":0.15,\"cost_score\":0,\"speed_score\":0,\"reliability_component\":0.75},{\"courier_id\":5,\"courier_code\":\"SHADOWFAX\",\"courier_name\":\"Shadowfax\",\"cost\":0,\"sla_min_days\":0,\"sla_max_days\":0,\"reliability_score\":0,\"is_express\":false,\"is_eligible\":false,\"ineligibility_reasons\":[\"does not serve pincode 587313\"],\"cost_source\":\"rate_card\",\"score\":null}]',0,NULL,NULL,1,'2026-09-15 20:47:24',NULL,NULL,NULL,NULL,1,0,1);
