DROP TABLE IF EXISTS `couriers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `couriers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `code` varchar(40) NOT NULL,
  `name` varchar(120) NOT NULL,
  `adapter` varchar(40) NOT NULL COMMENT 'shiprocket, delhivery, sandbox',
  `channel_code` varchar(60) DEFAULT NULL COMMENT 'Courier id within an aggregator',
  `logo_url` varchar(500) DEFAULT NULL,
  `support_phone` varchar(20) DEFAULT NULL,
  `tracking_url_template` varchar(500) DEFAULT NULL COMMENT 'Contains {awb}',
  `min_weight_grams` int(10) unsigned NOT NULL DEFAULT 0,
  `max_weight_grams` int(10) unsigned NOT NULL DEFAULT 30000,
  `max_order_value` decimal(12,2) DEFAULT NULL COMMENT 'Insurance ceiling; above this the courier is skipped',
  `max_length_mm` smallint(5) unsigned DEFAULT NULL,
  `max_width_mm` smallint(5) unsigned DEFAULT NULL,
  `max_height_mm` smallint(5) unsigned DEFAULT NULL,
  `handles_fragile` tinyint(1) NOT NULL DEFAULT 1,
  `priority` smallint(6) NOT NULL DEFAULT 100 COMMENT 'Lower wins ties; a commercial preference lever',
  `reliability_score` decimal(5,2) NOT NULL DEFAULT 80.00 COMMENT '0-100, maintained from delivery outcomes',
  `volumetric_divisor` smallint(5) unsigned NOT NULL DEFAULT 5000 COMMENT 'cm3 per kg; 5000 is the Indian norm, some couriers use 4000',
  `supports_pickup` tinyint(1) NOT NULL DEFAULT 1,
  `supports_label` tinyint(1) NOT NULL DEFAULT 1,
  `supports_manifest` tinyint(1) NOT NULL DEFAULT 1,
  `supports_rto` tinyint(1) NOT NULL DEFAULT 1,
  `is_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Operational switch, separate from is_active',
  `disabled_reason` varchar(255) DEFAULT NULL,
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Non-secret adapter options only' CHECK (json_valid(`settings`)),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_couriers_uuid` (`uuid`),
  UNIQUE KEY `uq_couriers_code` (`code`),
  KEY `idx_couriers_enabled` (`is_enabled`,`is_active`,`is_deleted`),
  CONSTRAINT `chk_couriers_weight_range` CHECK (`max_weight_grams` > `min_weight_grams`),
  CONSTRAINT `chk_couriers_reliability_range` CHECK (`reliability_score` >= 0 and `reliability_score` <= 100),
  CONSTRAINT `chk_couriers_divisor_positive` CHECK (`volumetric_divisor` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

