  CONSTRAINT `chk_slab_band_order` CHECK (`max_weight_grams` is null or `max_weight_grams` > `min_weight_grams`),
  CONSTRAINT `chk_slab_charge_not_negative` CHECK (`charge_amount` >= 0 and `per_extra_kg_amount` >= 0)
