/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_inventory_movements_immutable`
BEFORE UPDATE ON `inventory_movements`
FOR EACH ROW
BEGIN
