INSERT INTO `notification_templates` VALUES (1,'f4a0a218-b019-11f1-bc3b-9829a65a50b0','order.placed','sms','Order placed','transactional',NULL,'Order {{order_number}} received. Pay {{amount}} to confirm. We will notify you once payment is received.','[\"order_number\",\"amount\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(2,'f4a117a7-b019-11f1-bc3b-9829a65a50b0','order.confirmed','sms','Order confirmed','transactional',NULL,'Payment received for order {{order_number}}. We are preparing your order and will notify you when it ships.','[\"order_number\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(3,'f4a11ba3-b019-11f1-bc3b-9829a65a50b0','order.confirmed','email','Order confirmed','transactional','Your order {{order_number}} is confirmed','Hello {{customer_name}},\n\nThank you for your order. We have received your payment of {{amount}} and your order {{order_number}} is now confirmed.\n\nInvoice number: {{invoice_number}}\nDelivery to: {{delivery_address}}\n\nWe will send you tracking details as soon as your parcel is dispatched.','[\"customer_name\",\"order_number\",\"amount\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(4,'f4a11ec4-b019-11f1-bc3b-9829a65a50b0','order.shipped','sms','Order shipped','transactional',NULL,'Order {{order_number}} shipped via {{courier_name}}. Track: {{tracking_number}}. Expected by {{expected_date}}.','[\"order_number\",\"courier_name\",\"tracking_number\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(5,'f4a12188-b019-11f1-bc3b-9829a65a50b0','order.delivered','sms','Order delivered','transactional',NULL,'Order {{order_number}} delivered. Thank you for shopping with us.','[\"order_number\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(6,'f4a123e8-b019-11f1-bc3b-9829a65a50b0','order.cancelled','sms','Order cancelled','transactional',NULL,'Order {{order_number}} has been cancelled. Any amount paid will be refunded within 5-7 working days.','[\"order_number\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(7,'f4a12614-b019-11f1-bc3b-9829a65a50b0','payment.failed','sms','Payment failed','transactional',NULL,'Payment for order {{order_number}} did not complete. You can retry until {{expires_at}}.','[\"order_number\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(8,'f4a1284e-b019-11f1-bc3b-9829a65a50b0','wallet.credited','sms','Wallet credited','transactional',NULL,'{{amount}} added to your wallet. Balance: {{balance}}.','[\"amount\",\"balance\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(9,'f4a12a8a-b019-11f1-bc3b-9829a65a50b0','referral.rewarded','sms','Referral reward','transactional',NULL,'Your friend completed their first order. {{amount}} has been added to your wallet.','[\"amount\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(10,'f4a12cbf-b019-11f1-bc3b-9829a65a50b0','cart.abandoned','sms','Abandoned cart reminder','promotional',NULL,'You left {{item_count}} item(s) in your cart. Complete your order before stock changes.','[\"item_count\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(11,'f4a12ecd-b019-11f1-bc3b-9829a65a50b0','offer.announcement','sms','Offer announcement','promotional',NULL,'{{offer_title}}. Use code {{offer_code}} before {{valid_until}}.','[\"offer_title\",\"offer_code\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(12,'f4a13102-b019-11f1-bc3b-9829a65a50b0','wallet.expiring','sms','Wallet credit expiring','promotional',NULL,'{{amount}} of wallet credit expires on {{expiry_date}}. Use it on your next order.','[\"amount\",\"expiry_date\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(13,'f4afd6b5-b019-11f1-bc3b-9829a65a50b0','ticket.created','sms','Support ticket raised','transactional',NULL,'Support ticket {{ticket_number}} raised. We will respond within {{sla_hours}} hours.','[\"ticket_number\",\"sla_hours\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(14,'f4afdb8e-b019-11f1-bc3b-9829a65a50b0','ticket.replied','sms','Support reply','transactional',NULL,'We have replied to your ticket {{ticket_number}}. View it in your account.','[\"ticket_number\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(15,'f4afddf9-b019-11f1-bc3b-9829a65a50b0','ticket.resolved','sms','Support ticket resolved','transactional',NULL,'Ticket {{ticket_number}} has been resolved. Reply within {{reopen_days}} days if you need more help.','[\"ticket_number\",\"reopen_days\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(16,'f4afdfdf-b019-11f1-bc3b-9829a65a50b0','review.approved','sms','Review published','transactional',NULL,'Thank you - your review of {{product_name}} is now live.','[\"product_name\"]',NULL,NULL,1,NULL,'2026-09-14 14:24:55',NULL,NULL,NULL,NULL,0,24),(270,'68c3d501-b1a8-11f1-bd55-9829a65a50b0','marketing.broadcast','sms','Recurring lead broadcast','promotional',NULL,'{{headline}} {{detail}} Shop: 5staronline.in Reply STOP to opt out.','[\"headline\",\"detail\"]',NULL,NULL,1,NULL,'2026-09-16 13:57:11',NULL,NULL,NULL,NULL,0,1);
