--
-- Table structure for table `offers`
--

DROP TABLE IF EXISTS `offers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `offers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `code` varchar(40) NOT NULL COMMENT 'Internal reference, e.g. DIWALI25',
  `title` varchar(160) NOT NULL,
  `subtitle` varchar(240) DEFAULT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `offer_type` enum('festival','flash_sale','deal_of_day','category','combo','free_shipping','bogo') NOT NULL DEFAULT 'festival',
  `banner_image_path` varchar(255) DEFAULT NULL,
  `discount_type` enum('none','percentage','flat','free_delivery','free_items') NOT NULL DEFAULT 'none',
  `discount_value` decimal(10,2) NOT NULL DEFAULT 0.00,
  `buy_quantity` smallint(5) unsigned DEFAULT NULL COMMENT 'How many must be bought to earn the benefit',
  `get_quantity` smallint(5) unsigned DEFAULT NULL COMMENT 'How many are then free',
  `free_item_scope` enum('same_variant','cheapest_eligible') DEFAULT NULL COMMENT 'same_variant: free units come from the same pack the customer bought',
  `max_free_items_per_order` smallint(5) unsigned DEFAULT NULL COMMENT 'Total free units one order may earn; NULL means unlimited',
  `max_discount_amount` decimal(10,2) DEFAULT NULL,
  `min_order_value` decimal(10,2) DEFAULT NULL,
  `applies_to` enum('all','categories','products') NOT NULL DEFAULT 'all',
  `audience` enum('all','new_customers','specific_customer') NOT NULL DEFAULT 'all',
  `specific_user_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Required when audience = specific_customer',
  `channel` enum('all','pos','online') NOT NULL DEFAULT 'all',
  `stackable_with_coupon` tinyint(1) NOT NULL DEFAULT 0,
  `priority` smallint(5) unsigned NOT NULL DEFAULT 100 COMMENT 'Lower wins when two offers tie on discount value',
  `starts_date` datetime DEFAULT NULL,
  `ends_date` datetime DEFAULT NULL,
  `display_order` smallint(5) unsigned NOT NULL DEFAULT 100,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('draft','active','paused','expired') NOT NULL DEFAULT 'draft',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_offers_uuid` (`uuid`),
  UNIQUE KEY `uq_offers_code` (`code`),
  KEY `idx_offers_status` (`status`,`starts_date`,`ends_date`),
  KEY `idx_offers_type` (`offer_type`,`display_order`),
  KEY `idx_offers_audience` (`audience`,`specific_user_id`),
  KEY `fk_offers_specific_user` (`specific_user_id`),
  CONSTRAINT `fk_offers_specific_user` FOREIGN KEY (`specific_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_offers_percentage_range` CHECK (`discount_type` <> 'percentage' or `discount_value` > 0 and `discount_value` <= 100),
  CONSTRAINT `chk_offers_flat_positive` CHECK (`discount_type` <> 'flat' or `discount_value` > 0),
  CONSTRAINT `chk_offers_window` CHECK (`starts_date` is null or `ends_date` is null or `ends_date` > `starts_date`),
  CONSTRAINT `chk_offers_bogo_quantities` CHECK (`discount_type` <> 'free_items' or `buy_quantity` is not null and `buy_quantity` >= 1 and `get_quantity` is not null and `get_quantity` >= 1),
  CONSTRAINT `chk_offers_quantities_only_for_free_items` CHECK (`discount_type` = 'free_items' or `buy_quantity` is null and `get_quantity` is null),
  CONSTRAINT `chk_offers_specific_user` CHECK (`audience` <> 'specific_customer' or `specific_user_id` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

