DROP TABLE IF EXISTS `order_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order_assignments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `order_id` bigint(20) unsigned NOT NULL,
  `assigned_to_user_id` bigint(20) unsigned NOT NULL,
  `assigned_by_user_id` bigint(20) unsigned DEFAULT NULL COMMENT 'NULL when assigned automatically',
  `status` enum('assigned','accepted','completed','reassigned','released') NOT NULL DEFAULT 'assigned',
  `assignment_method` enum('auto','manual','self') NOT NULL DEFAULT 'auto',
  `assigned_date` datetime NOT NULL DEFAULT current_timestamp(),
  `accepted_date` datetime DEFAULT NULL,
  `completed_date` datetime DEFAULT NULL,
  `released_date` datetime DEFAULT NULL,
  `release_reason` varchar(255) DEFAULT NULL,
  `due_date` datetime DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  `active_order_id` bigint(20) unsigned GENERATED ALWAYS AS (case when `status` in ('assigned','accepted') and `is_deleted` = 0 then `order_id` end) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_order_assignments_uuid` (`uuid`),
  UNIQUE KEY `uq_order_assignments_active` (`active_order_id`),
  KEY `idx_order_assignments_order` (`order_id`),
  KEY `idx_order_assignments_assignee` (`assigned_to_user_id`,`status`),
  KEY `idx_order_assignments_due` (`status`,`due_date`),
  KEY `fk_order_assignments_assigner` (`assigned_by_user_id`),
  CONSTRAINT `fk_order_assignments_assignee` FOREIGN KEY (`assigned_to_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_order_assignments_assigner` FOREIGN KEY (`assigned_by_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_order_assignments_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
