  `unit_price` decimal(10,2) NOT NULL,
  `line_mrp` decimal(12,2) NOT NULL,
  `line_subtotal` decimal(12,2) NOT NULL,
  `product_discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `apportioned_discount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Share of the order-level discount carried by this line',
  `line_payable` decimal(12,2) NOT NULL,
  `taxable_value` decimal(12,2) NOT NULL,
  `tax_amount` decimal(12,2) NOT NULL,
  `gst_rate` decimal(5,2) NOT NULL,
  `line_weight_grams` int(10) unsigned NOT NULL DEFAULT 0,
  `is_gift` tinyint(1) NOT NULL DEFAULT 0,
  `gift_message` varchar(320) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_order_items_uuid` (`uuid`),
  UNIQUE KEY `uq_order_item_variant` (`order_id`,`variant_id`),
  KEY `idx_order_items_order` (`order_id`),
  KEY `idx_order_items_product` (`product_id`),
  KEY `idx_order_items_variant` (`variant_id`),
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_order_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `fk_order_items_variant` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `chk_order_items_quantity` CHECK (`quantity` > 0),
  CONSTRAINT `chk_order_items_tax_reconciles` CHECK (`taxable_value` + `tax_amount` = `line_payable`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
