--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `order_number` varchar(30) NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `cart_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Source cart, for support queries',
  `status` enum('created','awaiting_payment','confirmed','packed','ready_to_ship','assigned','shipped','out_for_delivery','delivered','cancelled','returned','refunded') NOT NULL DEFAULT 'created',
  `payment_status` enum('pending','processing','paid','failed','refunded','partially_refunded') NOT NULL DEFAULT 'pending',
  `payment_method` enum('upi','cod') NOT NULL DEFAULT 'upi' COMMENT 'upi = prepaid via a PaymentGatewayInterface driver; cod = collected on delivery, needs admin approval',
  `cod_approved_by` bigint(20) unsigned DEFAULT NULL,
  `cod_approved_date` datetime DEFAULT NULL,
  `cod_declined_reason` varchar(255) DEFAULT NULL,
  `currency_code` char(3) NOT NULL DEFAULT 'INR',
  `items_mrp_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `items_subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `product_discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `order_discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `order_surcharge` decimal(12,2) NOT NULL DEFAULT 0.00,
  `delivery_charge` decimal(12,2) NOT NULL DEFAULT 0.00,
  `delivery_charge_before_waiver` decimal(12,2) NOT NULL DEFAULT 0.00,
  `delivery_discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `taxable_value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tax_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `grand_total` decimal(12,2) NOT NULL,
  `wallet_applied` decimal(12,2) NOT NULL DEFAULT 0.00,
  `amount_payable` decimal(12,2) NOT NULL,
  `amount_paid` decimal(12,2) NOT NULL DEFAULT 0.00,
  `amount_refunded` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_savings` decimal(12,2) NOT NULL DEFAULT 0.00,
  `coupon_id` bigint(20) unsigned DEFAULT NULL,
  `coupon_code` varchar(30) DEFAULT NULL,
  `coupon_discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `offer_id` bigint(20) unsigned DEFAULT NULL,
  `offer_code` varchar(40) DEFAULT NULL,
  `offer_discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `ship_name` varchar(120) NOT NULL,
  `ship_mobile` varchar(15) NOT NULL,
  `ship_alternate_mobile` varchar(15) DEFAULT NULL,
  `ship_address_line1` varchar(180) NOT NULL,
  `ship_address_line2` varchar(180) DEFAULT NULL,
  `ship_landmark` varchar(120) DEFAULT NULL,
  `ship_city` varchar(90) NOT NULL,
  `ship_state` varchar(90) NOT NULL,
  `ship_pincode` varchar(10) NOT NULL,
  `ship_country` varchar(60) NOT NULL DEFAULT 'India',
  `source_address_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Informational only; may be deleted later',
  `delivery_zone_code` varchar(30) DEFAULT NULL,
  `delivery_sla_min_days` tinyint(3) unsigned DEFAULT NULL,
  `delivery_sla_max_days` tinyint(3) unsigned DEFAULT NULL,
  `expected_delivery_date` date DEFAULT NULL,
  `delivery_slot` varchar(60) DEFAULT NULL,
  `delivery_instructions` varchar(500) DEFAULT NULL,
  `total_weight_grams` int(10) unsigned NOT NULL DEFAULT 0,
  `courier_code` varchar(40) DEFAULT NULL,
  `courier_name` varchar(120) DEFAULT NULL,
  `tracking_number` varchar(80) DEFAULT NULL,
  `tracking_url` varchar(500) DEFAULT NULL,
  `shipped_date` datetime DEFAULT NULL,
  `is_gift` tinyint(1) NOT NULL DEFAULT 0,
  `gift_message` varchar(320) DEFAULT NULL,
  `otp_verified` tinyint(1) NOT NULL DEFAULT 0,
  `otp_verified_date` datetime DEFAULT NULL,
  `invoice_number` varchar(30) DEFAULT NULL,
  `invoice_date` datetime DEFAULT NULL,
  `invoice_financial_year` char(7) DEFAULT NULL,
  `placed_date` datetime DEFAULT NULL,
  `confirmed_date` datetime DEFAULT NULL,
  `delivered_date` datetime DEFAULT NULL,
  `cancelled_date` datetime DEFAULT NULL,
  `cancelled_by` bigint(20) unsigned DEFAULT NULL,
  `cancellation_reason` varchar(255) DEFAULT NULL,
  `expires_date` datetime DEFAULT NULL COMMENT 'Unpaid orders expire, releasing coupon and wallet credit',
  `customer_note` varchar(500) DEFAULT NULL,
  `internal_note` varchar(1000) DEFAULT NULL,
  `placed_ip` varchar(45) DEFAULT NULL,
  `placed_channel` enum('web','android','ios','admin') NOT NULL DEFAULT 'web',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orders_uuid` (`uuid`),
  UNIQUE KEY `uq_orders_number` (`order_number`),
  UNIQUE KEY `uq_orders_invoice_number` (`invoice_number`),
  KEY `idx_orders_user` (`user_id`,`created_date`),
  KEY `idx_orders_status` (`status`,`created_date`),
  KEY `idx_orders_payment_status` (`payment_status`,`created_date`),
  KEY `idx_orders_expiry` (`status`,`expires_date`),
  KEY `idx_orders_pincode` (`ship_pincode`),
  KEY `idx_orders_tracking` (`tracking_number`),
  KEY `idx_orders_coupon` (`coupon_id`),
  KEY `fk_orders_cart` (`cart_id`),
  KEY `idx_orders_cod_pending` (`payment_method`,`status`,`cod_approved_date`),
  CONSTRAINT `fk_orders_cart` FOREIGN KEY (`cart_id`) REFERENCES `carts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_orders_coupon` FOREIGN KEY (`coupon_id`) REFERENCES `coupons` (`id`),
  CONSTRAINT `fk_orders_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_orders_totals_not_negative` CHECK (`grand_total` >= 0 and `amount_payable` >= 0 and `wallet_applied` >= 0 and `amount_paid` >= 0 and `amount_refunded` >= 0),
  CONSTRAINT `chk_orders_wallet_within_total` CHECK (`wallet_applied` <= `grand_total`),
  CONSTRAINT `chk_orders_payable_split` CHECK (`amount_payable` = `grand_total` - `wallet_applied`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

