DROP TABLE IF EXISTS `pos_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pos_sales` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `sale_number` varchar(20) NOT NULL,
  `cashier_id` bigint(20) unsigned NOT NULL,
  `warehouse_id` bigint(20) unsigned NOT NULL,
  `customer_id` bigint(20) unsigned DEFAULT NULL,
  `walk_in_name` varchar(120) DEFAULT NULL,
  `walk_in_mobile` varchar(15) DEFAULT NULL,
  `payment_method` enum('cash','upi','card','other') NOT NULL,
  `subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `grand_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `amount_tendered` decimal(12,2) DEFAULT NULL COMMENT 'Cash only',
  `change_due` decimal(12,2) DEFAULT NULL COMMENT 'Cash only',
  `status` enum('completed','voided') NOT NULL DEFAULT 'completed',
  `voided_by` bigint(20) unsigned DEFAULT NULL,
  `voided_date` datetime DEFAULT NULL,
  `void_reason` varchar(255) DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pos_sales_uuid` (`uuid`),
  UNIQUE KEY `uq_pos_sales_number` (`sale_number`),
  KEY `idx_pos_sales_cashier` (`cashier_id`,`created_date`),
  KEY `idx_pos_sales_warehouse` (`warehouse_id`),
  KEY `idx_pos_sales_payment` (`payment_method`,`created_date`),
  KEY `idx_pos_sales_status` (`status`),
  KEY `fk_pos_sales_customer` (`customer_id`),
  KEY `fk_pos_sales_voided_by` (`voided_by`),
  CONSTRAINT `fk_pos_sales_cashier` FOREIGN KEY (`cashier_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_pos_sales_customer` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pos_sales_voided_by` FOREIGN KEY (`voided_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pos_sales_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `chk_pos_sales_totals_not_negative` CHECK (`subtotal` >= 0 and `discount_amount` >= 0 and `tax_amount` >= 0 and `grand_total` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

