DROP TABLE IF EXISTS `price_change_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `price_change_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `product_variant_id` bigint(20) unsigned NOT NULL,
  `reference_type` enum('purchase_order','manual','auto_apply') NOT NULL,
  `reference_id` bigint(20) unsigned DEFAULT NULL,
  `old_selling_price` decimal(10,2) NOT NULL,
  `new_selling_price` decimal(10,2) NOT NULL COMMENT 'Equal to old_selling_price when decision = keep_old: the decision is logged even when nothing changed',
  `purchase_price` decimal(12,4) DEFAULT NULL COMMENT 'The triggering inward unit cost, when applicable. Never the same field as average_cost or a selling price.',
  `average_cost` decimal(12,4) DEFAULT NULL,
  `decision` enum('manual','use_average','use_new','keep_old','auto_apply') NOT NULL,
  `pricing_rule_id` bigint(20) unsigned DEFAULT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `performed_by` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_price_change_log_uuid` (`uuid`),
  KEY `idx_price_change_log_variant` (`product_variant_id`,`created_date`),
  KEY `idx_price_change_log_reference` (`reference_type`,`reference_id`),
  KEY `fk_price_change_log_rule` (`pricing_rule_id`),
  CONSTRAINT `fk_price_change_log_rule` FOREIGN KEY (`pricing_rule_id`) REFERENCES `pricing_rules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_price_change_log_variant` FOREIGN KEY (`product_variant_id`) REFERENCES `product_variants` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
