--
-- Table structure for table `product_variants`
--

DROP TABLE IF EXISTS `product_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `product_variants` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `product_id` bigint(20) unsigned NOT NULL,
  `sku` varchar(50) NOT NULL,
  `barcode` varchar(64) DEFAULT NULL COMMENT 'EAN/UPC or similar, distinct from the internal SKU',
  `expiry_date` date DEFAULT NULL,
  `variant_name` varchar(80) NOT NULL COMMENT 'Display label, e.g. "500 g pouch"',
  `weight_grams` int(10) unsigned NOT NULL COMMENT 'Net product weight',
  `pack_length_mm` smallint(5) unsigned DEFAULT NULL COMMENT 'Outer packed dimensions, for volumetric weight',
  `pack_width_mm` smallint(5) unsigned DEFAULT NULL,
  `pack_height_mm` smallint(5) unsigned DEFAULT NULL,
  `is_fragile` tinyint(1) NOT NULL DEFAULT 0,
  `packed_weight_grams` int(10) unsigned DEFAULT NULL COMMENT 'Gross weight incl. packaging, for courier quoting',
  `pack_type` enum('pouch','jar','box','tin','gift_box','refill','other') NOT NULL DEFAULT 'pouch',
  `stock_unit_type` enum('weight','quantity') NOT NULL DEFAULT 'weight' COMMENT 'How inventory_stock.quantity for this variant should be read',
  `unit_label` varchar(20) DEFAULT NULL COMMENT 'Display only, e.g. pcs, box',
  `mrp` decimal(10,2) NOT NULL,
  `selling_price` decimal(10,2) NOT NULL,
  `offer_price` decimal(10,2) DEFAULT NULL,
  `offer_start_date` datetime DEFAULT NULL,
  `offer_end_date` datetime DEFAULT NULL,
  `max_order_quantity` smallint(5) unsigned NOT NULL DEFAULT 20,
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `display_order` smallint(5) unsigned NOT NULL DEFAULT 100,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_product_variants_uuid` (`uuid`),
  UNIQUE KEY `uq_product_variants_sku` (`sku`),
  UNIQUE KEY `uq_product_variants_barcode` (`barcode`),
  KEY `idx_variants_product` (`product_id`,`is_deleted`,`display_order`),
  KEY `idx_variants_weight` (`weight_grams`),
  KEY `idx_variants_price` (`selling_price`),
  KEY `idx_product_variants_expiry` (`expiry_date`),
  CONSTRAINT `fk_product_variants_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_variants_prices_positive` CHECK (`mrp` > 0 and `selling_price` > 0),
  CONSTRAINT `chk_variants_selling_not_above_mrp` CHECK (`selling_price` <= `mrp`),
  CONSTRAINT `chk_variants_offer_below_selling` CHECK (`offer_price` is null or `offer_price` < `selling_price`),
  CONSTRAINT `chk_variants_offer_window` CHECK (`offer_start_date` is null or `offer_end_date` is null or `offer_end_date` > `offer_start_date`),
  CONSTRAINT `chk_variants_weight_positive` CHECK (`weight_grams` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

