--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `category_id` bigint(20) unsigned NOT NULL COMMENT 'Leaf category the product sits in',
  `product_code` varchar(40) NOT NULL COMMENT 'Internal reference, e.g. SPC-TURMERIC',
  `slug` varchar(180) NOT NULL,
  `name` varchar(180) NOT NULL,
  `brand` varchar(120) DEFAULT NULL,
  `short_description` varchar(320) DEFAULT NULL,
  `description` mediumtext DEFAULT NULL,
  `ingredients` text DEFAULT NULL,
  `usage_instructions` text DEFAULT NULL,
  `storage_instructions` varchar(320) DEFAULT NULL,
  `shelf_life_days` smallint(5) unsigned DEFAULT NULL,
  `origin_country` varchar(80) NOT NULL DEFAULT 'India',
  `origin_region` varchar(120) DEFAULT NULL COMMENT 'e.g. Erode, Tamil Nadu',
  `hsn_code` varchar(15) DEFAULT NULL COMMENT 'GST classification',
  `gst_rate` decimal(5,2) NOT NULL DEFAULT 5.00,
  `fssai_license_no` varchar(30) DEFAULT NULL,
  `is_organic` tinyint(1) NOT NULL DEFAULT 0,
  `is_vegetarian` tinyint(1) NOT NULL DEFAULT 1,
  `is_gift_packable` tinyint(1) NOT NULL DEFAULT 1,
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `published_date` datetime DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `display_order` smallint(5) unsigned NOT NULL DEFAULT 100,
  `search_keywords` varchar(500) DEFAULT NULL COMMENT 'Synonyms and regional names: haldi, manjal',
  `rating_average` decimal(3,2) NOT NULL DEFAULT 0.00,
  `rating_count` int(10) unsigned NOT NULL DEFAULT 0,
  `review_count` int(10) unsigned NOT NULL DEFAULT 0,
  `sold_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Units sold, drives popularity sort',
  `view_count` int(10) unsigned NOT NULL DEFAULT 0,
  `meta_title` varchar(180) DEFAULT NULL,
  `meta_description` varchar(320) DEFAULT NULL,
  `inventory_tracking` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Overrides the category default when set; same shape' CHECK (json_valid(`inventory_tracking`)),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_products_uuid` (`uuid`),
  UNIQUE KEY `uq_products_code` (`product_code`),
  UNIQUE KEY `uq_products_slug` (`slug`),
  KEY `idx_products_category` (`category_id`,`status`,`is_deleted`),
  KEY `idx_products_status` (`status`,`is_deleted`,`is_active`),
  KEY `idx_products_featured` (`is_featured`,`status`,`display_order`),
  KEY `idx_products_rating` (`rating_average`,`rating_count`),
  KEY `idx_products_popularity` (`sold_count`),
  KEY `idx_products_created` (`created_date`),
  FULLTEXT KEY `ft_products_search` (`name`,`short_description`,`search_keywords`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

