INSERT INTO `products` VALUES (1,'f459c2a7-b019-11f1-bc3b-9829a65a50b0',9,'DEMO-TURMERIC','organic-turmeric-powder','Organic Turmeric Powder','Spice & Dry Fruits','Single-origin Erode turmeric, stone-ground, 3.5% curcumin','Sun-dried Erode turmeric fingers, stone-ground in small batches to protect the volatile oils. Deep ochre colour, earthy aroma, no added colour or starch.','100% turmeric (Curcuma longa)',NULL,'Store in a cool, dry place away from direct sunlight. Keep the pouch sealed.',540,'India','Erode, Tamil Nadu','09103020',5.00,NULL,1,1,1,'published','2026-09-14 14:24:54',1,10,'haldi, manjal, arishina, curcumin, halad, yellow spice',0.00,0,0,0,6,NULL,NULL,NULL,NULL,'2026-09-14 14:24:54',NULL,NULL,NULL,NULL,1,0,24),(2,'f45a010b-b019-11f1-bc3b-9829a65a50b0',11,'DEMO-ALMOND','california-almonds','California Almonds','Spice & Dry Fruits','Hand-sorted premium California almonds, crisp and unsalted','Non-pareil grade California almonds, hand-sorted for uniform size and screened for shell fragments. Raw and unsalted.','100% almonds (Prunus dulcis)',NULL,'Refrigerate after opening to preserve crispness.',365,'India','Imported, packed in Karnataka','08021200',12.00,NULL,0,1,1,'published','2026-09-14 14:24:54',1,20,'badam, badaam, nuts, almond, akhrot alternative',0.00,0,0,0,9,NULL,NULL,NULL,NULL,'2026-09-14 14:24:54',NULL,NULL,NULL,NULL,1,0,24),(3,'f45a07f2-b019-11f1-bc3b-9829a65a50b0',8,'DEMO-CARDAMOM','green-cardamom-8mm','Green Cardamom 8mm','Spice & Dry Fruits','Bold 8mm Idukki cardamom pods, intensely aromatic','Grade AGEB 8mm green cardamom from the Idukki hills. Plump, tightly closed pods with a high volatile-oil content.','100% green cardamom (Elettaria cardamomum)',NULL,'Keep in an airtight container; do not refrigerate.',450,'India','Idukki, Kerala','09083110',5.00,NULL,0,1,1,'published','2026-09-14 14:24:54',1,30,'elaichi, elachi, yelakkai, cardamom, hari elaichi',0.00,0,0,0,3,NULL,NULL,NULL,NULL,'2026-09-14 14:24:54',NULL,NULL,NULL,NULL,1,0,24),(11,'3e8c