DROP TABLE IF EXISTS `purchase_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `po_number` varchar(20) NOT NULL,
  `vendor_id` bigint(20) unsigned NOT NULL,
  `warehouse_id` bigint(20) unsigned NOT NULL,
  `purchase_date` date NOT NULL,
  `invoice_reference` varchar(80) DEFAULT NULL,
  `items_subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `other_charges` decimal(12,2) NOT NULL DEFAULT 0.00,
  `transport_charge` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Flat rupee transportation charge for this purchase, before percentage allocation',
  `transport_included_in_cost` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'When 1, unit_cost already includes transport and transport_charge/transport_percent are not applied',
  `transport_percent` decimal(7,4) DEFAULT NULL COMMENT 'transport_charge / items_subtotal * 100 at creation time, stored so a later view does not recompute from data that may have since changed',
  `tax_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `grand_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `payment_status` enum('unpaid','partial','paid') NOT NULL DEFAULT 'unpaid' COMMENT 'Derived from amount_paid vs grand_total, never set independently',
  `amount_paid` decimal(12,2) NOT NULL DEFAULT 0.00,
  `amount_returned` decimal(12,2) NOT NULL DEFAULT 0.00,
  `notes` varchar(500) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_purchase_orders_uuid` (`uuid`),
  UNIQUE KEY `uq_purchase_orders_number` (`po_number`),
  KEY `idx_purchase_orders_vendor` (`vendor_id`,`purchase_date`),
  KEY `idx_purchase_orders_warehouse` (`warehouse_id`),
  KEY `idx_purchase_orders_date` (`purchase_date`),
  CONSTRAINT `fk_purchase_orders_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`),
  CONSTRAINT `fk_purchase_orders_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `chk_purchase_orders_amount_paid_range` CHECK (`amount_paid` >= 0 and `amount_paid` <= `grand_total`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

