--
-- Table structure for table `referrals`
--

DROP TABLE IF EXISTS `referrals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `referrals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `referrer_user_id` bigint(20) unsigned NOT NULL,
  `referee_user_id` bigint(20) unsigned NOT NULL,
  `referral_code_used` varchar(20) NOT NULL,
  `status` enum('pending','qualified','rewarded','cancelled') NOT NULL DEFAULT 'pending',
  `qualifying_order_reference` varchar(50) DEFAULT NULL,
  `qualifying_order_value` decimal(10,2) DEFAULT NULL,
  `referrer_reward_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `referee_reward_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `qualified_date` datetime DEFAULT NULL,
  `rewarded_date` datetime DEFAULT NULL,
  `cancelled_reason` varchar(255) DEFAULT NULL,
  `signup_ip` varchar(45) DEFAULT NULL COMMENT 'Retained for fraud review',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_referrals_uuid` (`uuid`),
  UNIQUE KEY `uq_referrals_referee` (`referee_user_id`),
  KEY `idx_referrals_referrer` (`referrer_user_id`,`status`),
  KEY `idx_referrals_status` (`status`,`created_date`),
  CONSTRAINT `fk_referrals_referee` FOREIGN KEY (`referee_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_referrals_referrer` FOREIGN KEY (`referrer_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_referrals_not_self` CHECK (`referrer_user_id` <> `referee_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

