--
-- Table structure for table `refresh_tokens`
--

DROP TABLE IF EXISTS `refresh_tokens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `refresh_tokens` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `token_hash` char(64) NOT NULL COMMENT 'SHA-256 of the opaque token',
  `device_id` varchar(100) DEFAULT NULL,
  `device_name` varchar(120) DEFAULT NULL,
  `platform` enum('web','android','ios','other') NOT NULL DEFAULT 'web',
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `expires_date` datetime NOT NULL,
  `revoked_date` datetime DEFAULT NULL,
  `revoked_reason` varchar(50) DEFAULT NULL COMMENT 'logout | rotated | reuse_detected | password_reset | admin',
