--
-- Table structure for table `shipment_events`
--

DROP TABLE IF EXISTS `shipment_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `shipment_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `shipment_id` bigint(20) unsigned NOT NULL,
  `courier_event_id` varchar(160) DEFAULT NULL COMMENT 'Courier scan id, when they provide one',
  `event_code` varchar(60) DEFAULT NULL,
  `status` varchar(60) NOT NULL,
  `title` varchar(180) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `location` varchar(180) DEFAULT NULL,
  `occurred_date` datetime NOT NULL,
  `is_customer_visible` tinyint(1) NOT NULL DEFAULT 1,
  `source` enum('webhook','poll','manual') NOT NULL DEFAULT 'webhook',
  `raw_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`raw_payload`)),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_shipment_events_uuid` (`uuid`),
  UNIQUE KEY `uq_shipment_event_courier_id` (`shipment_id`,`courier_event_id`),
  KEY `idx_shipment_events_shipment` (`shipment_id`,`occurred_date`),
  CONSTRAINT `fk_shipment_events_shipment` FOREIGN KEY (`shipment_id`) REFERENCES `shipments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `shipment_events`
--

LOCK TABLES `shipment_events` WRITE;
/*!40000 ALTER TABLE `shipment_events` DISABLE KEYS */;
