--
-- Table structure for table `shipments`
--

DROP TABLE IF EXISTS `shipments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `shipments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `shipment_number` varchar(30) NOT NULL,
  `order_id` bigint(20) unsigned NOT NULL,
  `courier_id` bigint(20) unsigned NOT NULL,
  `awb_number` varchar(80) DEFAULT NULL COMMENT 'Airway bill / tracking number',
  `courier_shipment_id` varchar(120) DEFAULT NULL COMMENT 'Identifier in the courier system',
  `label_url` varchar(500) DEFAULT NULL,
  `label_generated_date` datetime DEFAULT NULL,
  `manifest_id` bigint(20) unsigned DEFAULT NULL,
  `pickup_request_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('created','booked','label_generated','pickup_scheduled','picked_up','in_transit','out_for_delivery','delivered','failed_delivery','rto_initiated','rto_delivered','cancelled','lost') NOT NULL DEFAULT 'created',
  `actual_weight_grams` int(10) unsigned NOT NULL,
  `volumetric_weight_grams` int(10) unsigned NOT NULL DEFAULT 0,
  `chargeable_weight_grams` int(10) unsigned NOT NULL COMMENT 'The greater of actual and volumetric; couriers bill on this',
  `length_mm` smallint(5) unsigned DEFAULT NULL,
  `width_mm` smallint(5) unsigned DEFAULT NULL,
  `height_mm` smallint(5) unsigned DEFAULT NULL,
  `used_default_dimensions` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'True when a variant had no measurements and a default box was assumed',
  `declared_value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `courier_charge` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'What we pay the courier, not what the customer paid',
  `customer_paid_delivery` decimal(10,2) NOT NULL DEFAULT 0.00,
  `promised_sla_min_days` tinyint(3) unsigned DEFAULT NULL,
  `promised_sla_max_days` tinyint(3) unsigned DEFAULT NULL,
  `estimated_delivery_date` date DEFAULT NULL,
  `pickup_scheduled_date` datetime DEFAULT NULL,
  `picked_up_date` datetime DEFAULT NULL,
  `delivered_date` datetime DEFAULT NULL,
  `delivery_attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `last_scan_date` datetime DEFAULT NULL,
  `last_scan_location` varchar(180) DEFAULT NULL,
  `last_scan_status` varchar(120) DEFAULT NULL,
  `rto_reason` varchar(255) DEFAULT NULL,
  `failure_reason` varchar(255) DEFAULT NULL,
  `booking_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`booking_response`)),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_date` datetime DEFAULT NULL,
